CREATE TEMP TABLE lab_queue AS
SELECT n AS id, CASE WHEN n % 1000 = 0 THEN 'pending' ELSE 'done' END AS status
FROM generate_series(1, 100000) AS n;
ANALYZE lab_queue;
EXPLAIN (ANALYZE, BUFFERS)
SELECT id FROM lab_queue WHERE status = 'pending' ORDER BY id LIMIT 10;

CREATE INDEX lab_pending_id ON lab_queue (id) WHERE status = 'pending';
EXPLAIN (ANALYZE, BUFFERS)
SELECT id FROM lab_queue WHERE status = 'pending' ORDER BY id LIMIT 10;
SELECT id FROM lab_queue WHERE status = 'pending' ORDER BY id LIMIT 10;

